  min-height: 280px;
}

.split-right-page[data-target='page-map'] .mvu-holo-map-card:last-child {
  min-height: 330px;
}

.mvu-modal-mask {
  position: fixed;
  inset: 0;
  z-index: 120;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 14px;
  pointer-events: auto;
}

.mvu-modal-mask.show {
  display: flex;
}

.mvu-modal-panel {
  position: relative;
  z-index: 1;
  isolation: isolate;
  pointer-events: auto;
  width: 100%;
  max-width: clamp(320px, 92vw, 760px);
  max-height: min(86svh, 920px);
  min-height: min(560px, calc(100svh - 40px));
  display: flex;
  flex-direction: column;
  overflow: hidden;
  opacity: 0;
  transform: translateY(10px) scale(0.985);
}

@keyframes modalMaskFade {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}

@keyframes modalPanelBoot {
  0% {
    opacity: 0;
    filter: brightness(1.6) blur(3px);
    transform: perspective(900px) rotateX(5deg) translateY(16px) scale(0.985);
  }
  45% {
    opacity: 1;
  }
  100% {
    opacity: 1;
    filter: brightness(1) blur(0);
    transform: perspective(900px) rotateX(0deg) translateY(0) scale(1);
  }
}

@keyframes drawerLeftBoot {
