  font-size: var(--mvu-font-sm, 12px);
}

.cp-permission-row:not([data-cabin-plane]):not([data-cabin-flow]) {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 11px;
}

.cp-row-main:not([data-cabin-plane]):not([data-cabin-flow]) {
  min-width: 0;
}

.cp-permission-use:not([data-cabin-plane]):not([data-cabin-flow]) {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
}

.cp-permission-use select {
  min-width: 0;
  min-height: 30px;
  max-width: 280px;
  border: 1px solid rgba(143, 233, 255, 0.2);
  border-radius: 5px;
  background: rgba(4, 13, 18, 0.82);
  color: var(--text-main);
  padding: 5px 7px;
}

.cp-icon-btn:not([data-cabin-plane]):not([data-cabin-flow]) {
  width: 30px;
  height: 30px;
  padding: 0;
  font-size: 20px;
}

.cp-icon-btn.danger:not([data-cabin-plane]):not([data-cabin-flow]) {
  border-color: rgba(248, 113, 113, 0.34);
  color: #fecaca;
}

.cp-groups:not([data-cabin-plane]):not([data-cabin-flow]) {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(310px, 1fr));
  gap: 10px;
  margin: 12px 0;
}

.cp-group:not([data-cabin-plane]):not([data-cabin-flow]) {
  min-width: 0;
}

.cp-bracket:not([data-cabin-plane]):not([data-cabin-flow]) {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(210px, 1fr);
  gap: 12px;
  overflow-x: auto;
  padding: 12px 0;
}

.cp-bracket-round:not([data-cabin-plane]):not([data-cabin-flow]) {
  display: flex;
  flex-direction: column;
  justify-content: space-around;
  gap: 10px;
  min-width: 0;
}

.cp-match:not([data-cabin-plane]):not([data-cabin-flow]) {
  padding: 10px;
}

.cp-match-meta:not([data-cabin-plane]):not([data-cabin-flow]),
.cp-match-sides:not([data-cabin-plane]):not([data-cabin-flow]) {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.cp-match-sides:not([data-cabin-plane]):not([data-cabin-flow]) {
  min-height: 36px;
  margin: 5px 0;
}

.cp-match-sides b {
  min-width: 0;
  overflow-wrap: anywhere;
}

.cp-match-sides b.winner {
  color: #f8d98a;
}

.cp-match-sides i {
  color: #8fe9ff;
  font-style: normal;
  font-size: max(var(--dc-native-min-font, 0px), 11px);
}

.cp-match-actions:not([data-cabin-plane]):not([data-cabin-flow]) {
  justify-content: flex-end;
  margin-top: 8px;
}

.cp-empty:not([data-cabin-plane]):not([data-cabin-flow]) {
  padding: 22px 12px;
  border: 1px dashed rgba(143, 233, 255, 0.2);
  border-radius: 7px;
  color: var(--text-sub);
  text-align: center;
}

@media (max-width: 720px) {
  .cp-event-layout:not([data-cabin-plane]):not([data-cabin-flow]) {
    grid-template-columns: 1fr;
  }

  .cp-event-list:not([data-cabin-plane]):not([data-cabin-flow]) {
    display: grid;
    grid-auto-flow: column;
    grid-auto-columns: minmax(145px, 1fr);
    overflow-x: auto;
  }

  .cp-register-form:not([data-cabin-plane]):not([data-cabin-flow]),
  .cp-stage-row:not([data-cabin-plane]):not([data-cabin-flow]) {
    grid-template-columns: 1fr;
  }

  .cp-bracket:not([data-cabin-plane]):not([data-cabin-flow]) {
    display: flex;
    flex-direction: column;
    overflow: visible;
  }

  .cp-event-head:not([data-cabin-plane]):not([data-cabin-flow]) {
    align-items: stretch;
    flex-direction: column;
  }
}

.mvu-modal-panel.drawer-left .archive-modal-grid:not([data-cabin-plane]):not([data-cabin-flow]),
.mvu-modal-panel.drawer-left .equipment-layout,
.mvu-modal-panel.drawer-left .relation-layout,
.mvu-modal-panel.drawer-left .intel-layout,
.mvu-modal-panel.drawer-left .profile-snapshot {
  grid-template-columns: 1fr;
}

.mvu-modal-panel.drawer-left .archive-card.full:not([data-cabin-plane]):not([data-cabin-flow]) {
  grid-column: auto;
}

.mvu-modal-panel.drawer-left .archive-card-title {
  white-space: normal;
}

.mvu-modal-panel.drawer-left .archive-card-head:not([data-cabin-plane]):not([data-cabin-flow]) {
  flex-wrap: wrap;
  align-items: center;
}

.mvu-modal-panel.drawer-left .archive-card-head:not([data-cabin-plane]):not([data-cabin-flow])::after {
  min-width: 100%;
  order: 3;
}

.mvu-modal-panel.drawer-left .inventory-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.radar-shell {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 8px;
}

.radar-visual {
  display: flex;
  justify-content: center;
  align-items: center;
}

.radar-svg {
  width: 100%;
  max-width: 220px;
  height: auto;
  overflow: visible;
}

.radar-grid-line {
  fill: none;
  stroke: var(--mvu-color-line-soft, rgba(255, 255, 255, 0.08));
  stroke-width: 1;
}

.radar-axis-line {
  stroke: color-mix(in srgb, var(--主题主色) 16%, transparent);
  stroke-width: 1;
}

.radar-data-shape {
  fill: color-mix(in srgb, var(--主题主色) 22%, transparent);
  stroke: color-mix(in srgb, var(--主题主色) 90%, #ffffff);
  stroke-width: 2.2;
  filter: drop-shadow(0 0 7px color-mix(in srgb, var(--主题主色) 42%, transparent));
}

.radar-data-shape.gold {
  fill: color-mix(in srgb, var(--武魂舞台魂色, var(--主题高光)) 20%, transparent);
  stroke: color-mix(in srgb, var(--武魂舞台魂色, var(--主题高光)) 86%, #ffffff);
}

.radar-label {
  fill: var(--全息标签文字);
  font-size: var(--mvu-font-xs, 10px);
  font-family: var(--font-tech);
  filter: drop-shadow(0 0 4px #000) drop-shadow(0 0 5px color-mix(in srgb, var(--主题主色) 22%, transparent));
}

.radar-legend {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}

.legend-chip {
  border-radius: 0;
  padding: 7px 8px;
  background: transparent;
  border: 0;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.legend-chip b {
  display: block;
  margin-bottom: 3px;
  font-size: var(--mvu-font-xs, 10px);
  color: var(--全息标签文字);
  font-weight: 500;
}

.legend-chip span {
  font-size: var(--mvu-font-sm, 12px);
  color: var(--全息数值文字);
  text-shadow: var(--全息数值字影);
  line-height: 1.3;
}

.archive-card-head:not([data-cabin-plane]):not([data-cabin-flow]) {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

:where(#mvu-unified-mount, #detailModal, .mvu-hover-card-floating--portal) .archive-card-title:not([data-cabin-flow]) {
  font-family: var(--font-title);
  font-size: var(--mvu-font-md, 14px);
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: 0.55px;
  color: var(--全息标题文字);
  white-space: normal;
}

.archive-card-head:not([data-cabin-plane]):not([data-cabin-flow])::after {
  content: none;
  display: none;
}

/* Compact Archive Grid & Figure Board */
.archive-tile-grid:not([data-cabin-plane]):not([data-cabin-flow]) {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 6px;
  margin-bottom: 8px;
}

.archive-tile-grid .archive-tile:not([data-cabin-plane]):not([data-cabin-flow]) {
  padding: 6px 8px;
  min-height: 44px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.archive-tile-grid .archive-tile b {
  font-size: var(--mvu-font-xs, 10px);
  color: var(--全息标签文字);
  margin-bottom: 3px;
  font-weight: 500;
  letter-spacing: 0.5px;
}

.archive-tile-grid .archive-tile span {
  min-width: 0;
  font-size: var(--mvu-font-sm, 12px);
  color: var(--全息数值文字);
  line-height: 1.2;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.figure-board {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: radial-gradient(circle at center, color-mix(in srgb, var(--主题主色) 4%, transparent) 0%, transparent 65%);
  margin: 10px 0;
}

.figure-core {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 45px;
  height: 45px;
  background: color-mix(in srgb, var(--主题主色) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--主题主色) 30%, transparent);
  border-radius: 50%;
  display: grid;
  place-items: center;
  text-align: center;
  font-size: var(--mvu-font-xs, 10px);
  color: var(--cyan);
  z-index: 2;
  box-shadow: 0 0 15px rgba(0, 229, 255, 0.15);
}

.figure-slot {
  position: absolute;
  transform: translate(-50%, -50%);
  background: var(--mvu-color-panel-soft, rgba(255, 255, 255, 0.03));
  border: 1px solid var(--mvu-color-line-muted, rgba(255, 255, 255, 0.1));
  padding: 4px 8px;
  border-radius: var(--mvu-radius-xs, 4px);
  font-size: var(--mvu-font-xs, 10px);
  color: var(--text-dim);
  white-space: nowrap;
  z-index: 3;
  transition: 0.2s ease;
}

.figure-slot.on {
  background: var(--mvu-color-cyan-fill, rgba(0, 229, 255, 0.08));
  border-color: rgba(0, 229, 255, 0.25);
  color: var(--cyan);
  box-shadow: 0 0 10px rgba(0, 229, 255, 0.1);
}

.figure-slot.warn {
  background: rgba(255, 77, 122, 0.08);
  border-color: rgba(255, 77, 122, 0.25);
  color: var(--red);
  box-shadow: 0 0 10px rgba(255, 77, 122, 0.1);
}

.figure-slot.off {
  opacity: 0.5;
  background: rgba(255, 255, 255, 0.01);
  border-color: var(--mvu-color-panel-muted, rgba(255, 255, 255, 0.05));
}

.figure-slot.clickable:hover,
.figure-core.clickable:hover {
  background: color-mix(in srgb, var(--主题主色) 18%, var(--暗场底板强));
  border-color: var(--主题主色);
  color: var(--主题主色);
  box-shadow:
    inset 0 0 12px color-mix(in srgb, var(--主题主色) 18%, transparent),
    0 0 20px color-mix(in srgb, var(--主题主色) 48%, transparent);
  cursor: pointer;
}

.armory-quick-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 4px;
}

.armory-quick-actions .tag-chip {
  flex: 1 1 calc(33.333% - 6px);
  text-align: center;
  justify-content: center;
  padding: 6px 8px;
  font-size: var(--mvu-font-sm, 12px);
}

.archive-card-head .state-tag {
  margin-left: auto;
  flex: 0 0 auto;
}

/* Unified title system */
#detailModal .modal-title,
:where(#mvu-unified-mount, #detailModal) .archive-card-title:not([data-cabin-plane]):not([data-cabin-flow]) {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  margin: 0;
  font-family: var(--font-title);
  font-size: var(--mvu-font-md, 14px);
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: 0.55px;
  color: var(--文字主色);
  -webkit-font-smoothing: antialiased;
  text-rendering: geometricPrecision;
  white-space: normal;
  margin-bottom: 16px;
}
:where(#mvu-unified-mount, #detailModal, .mvu-hover-card-floating--portal) .archive-card-title:not([data-cabin-plane]):not([data-cabin-flow])::before {
  content: none;
  display: none;
}

:where(#mvu-unified-mount, #detailModal, .mvu-hover-card-floating--portal) .archive-card-title:not([data-cabin-flow]) {
  color: var(--全息材质侧线);
}

#detailModal .modal-title::after,
:where(#mvu-unified-mount, #detailModal) .archive-card-title:not([data-cabin-plane]):not([data-cabin-flow])::after {
  content: none;
  display: none;
}

.topology-board {
  position: relative;
  z-index: 1;
  min-height: 220px;
  border-radius: var(--mvu-radius-md, 12px);
  border: 1px solid var(--mvu-color-panel-muted, rgba(255, 255, 255, 0.05));
  background:
    radial-gradient(circle at 50% 50%, rgba(77, 240, 255, 0.09), transparent 58%),
    linear-gradient(rgba(77, 240, 255, 0.028) 1px, transparent 1px),
    linear-gradient(90deg, rgba(77, 240, 255, 0.028) 1px, transparent 1px),
    linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0.01));
  background-size: auto, 22px 22px, 22px 22px, auto;
  overflow: visible;
}

.topology-board:has(.topology-node.interactive-ring:hover),
.topology-board:has(.topology-node.mvu-hover-floating-active) {
  z-index: 1200;
}

.topology-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.topology-link {
  stroke: var(--mvu-color-cyan-line, rgba(0, 229, 255, 0.18));
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-dasharray: 6 8;
  filter: drop-shadow(0 0 5px rgba(77, 240, 255, 0.28));
  animation: relation-link-flow 5s linear infinite;
}

.topology-link.gold {
  stroke: rgba(255, 215, 0, 0.2);
}

.topology-link.alert {
  stroke: rgba(255, 77, 122, 0.24);
}

.topology-node {
  position: absolute;
  transform: translate(-50%, -50%);
  min-width: 78px;
  max-width: 112px;
  min-height: 38px;
  padding: 6px 9px;
  border-radius: var(--mvu-radius-sm, 8px);
  background: rgba(7, 16, 30, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.06);
  box-shadow: inset 0 0 12px rgba(255, 255, 255, 0.02);
  -webkit-font-smoothing: antialiased;
}

.topology-node.center {
  min-width: 88px;
  min-height: 48px;
  border-color: rgba(77, 240, 255, 0.52);
  background:
    radial-gradient(circle at 50% 0%, rgba(77, 240, 255, 0.18), transparent 68%),
    rgba(7, 20, 32, 0.92);
  box-shadow:
    0 0 0 1px rgba(77, 240, 255, 0.08),
    0 0 24px rgba(77, 240, 255, 0.22),
    inset 0 0 18px rgba(77, 240, 255, 0.08);
  animation: relation-self-pulse 3.4s ease-in-out infinite;
}

.topology-node.gold {
  border-color: var(--mvu-color-gold-line, rgba(255, 215, 0, 0.22));
  background: rgba(255, 215, 0, 0.06);
}

.topology-node.warn {
  border-color: rgba(255, 77, 122, 0.24);
  background: rgba(255, 77, 122, 0.05);
}

.topology-node.relation-node--person {
  padding-left: 12px;
}

.topology-node.relation-node--person::before {
  content: '';
  position: absolute;
  left: 5px;
  top: 7px;
  bottom: 7px;
  width: 2px;
  border-radius: var(--mvu-radius-pill, 999px);
  background: rgba(143, 233, 255, 0.4);
  box-shadow: 0 0 8px currentColor;
}

.topology-node.relation-kind-friendly {
  border-color: rgba(104, 255, 186, 0.3);
}

.topology-node.relation-kind-friendly::before {
  background: rgba(104, 255, 186, 0.78);
}

.topology-node.relation-kind-romance {
  border-color: rgba(255, 120, 176, 0.34);
}

.topology-node.relation-kind-romance::before {
  background: rgba(255, 120, 176, 0.8);
}

.topology-node.relation-kind-hostile {
  border-color: rgba(255, 94, 115, 0.38);
}

.topology-node.relation-kind-hostile::before {
  background: rgba(255, 94, 115, 0.8);
}

.topology-node.relation-kind-neutral::before {
  background: rgba(143, 233, 255, 0.52);
}

.topology-node > b {
  display: block;
  margin-bottom: 1px;
  font-size: var(--mvu-font-xs, 10px);
  color: var(--white);
  font-weight: 700;
  line-height: 1.15;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.topology-node > span {
  display: block;
  font-size: max(var(--dc-native-min-font, 0px), 9px);
  color: var(--text-sub);
  line-height: 1.2;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.topology-node.interactive-ring {
  cursor: pointer;
  z-index: 100;
}

.topology-node.interactive-ring:hover,
.topology-node.interactive-ring.mvu-hover-floating-active {
  z-index: 1300;
  box-shadow: var(--shadow-cyan);
  border-color: rgba(0, 229, 255, 0.4);
}

@keyframes relation-link-flow {
  to {
    stroke-dashoffset: -56;
  }
}

@keyframes relation-self-pulse {
  0%,
  100% {
    box-shadow:
      0 0 0 1px rgba(77, 240, 255, 0.08),
      0 0 18px rgba(77, 240, 255, 0.18),
      inset 0 0 18px rgba(77, 240, 255, 0.08);
  }
  50% {
    box-shadow:
      0 0 0 1px rgba(77, 240, 255, 0.16),
      0 0 32px rgba(77, 240, 255, 0.32),
      inset 0 0 22px rgba(77, 240, 255, 0.12);
  }
}

@keyframes relation-dossier-refresh {
  0% {
    opacity: 0.58;
    filter: saturate(1.35) brightness(1.08);
    transform: translateY(4px);
  }
  100% {
    opacity: 1;
    filter: none;
    transform: translateY(0);
  }
}

.topology-node.interactive-ring .relation-hover-card {
  position: absolute;
  top: calc(100% - 10px);
  left: 50%;
  width: 220px;
  box-sizing: border-box;
  padding: 10px;
  border-radius: var(--mvu-radius-md, 12px);
  background: rgba(6, 16, 30, 0.97);
  border: 1px solid rgba(143, 233, 255, 0.16);
  box-shadow:
    0 14px 30px rgba(0, 0, 0, 0.24),
    inset 0 0 12px rgba(143, 233, 255, 0.05);
  z-index: 1400;
  text-align: left;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translate(-50%, 6px);
  transition:
    opacity 0.18s ease,
    transform 0.18s ease,
    visibility 0.18s ease;
  -webkit-font-smoothing: antialiased;
}

.topology-node.interactive-ring.hover-up .relation-hover-card {
  top: auto;
  bottom: calc(100% - 10px);
  transform: translate(-50%, 6px);
}

.topology-node.interactive-ring .relation-hover-title {
  display: block;
  margin-bottom: 3px;
  font-size: var(--mvu-font-sm, 12px);
  line-height: 1.25;
  color: var(--white);
  font-weight: 700;
}

.topology-node.interactive-ring .relation-hover-desc {
  display: block;
  margin-bottom: 7px;
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1.35;
  color: var(--text-sub);
  white-space: normal;
}

.topology-node.interactive-ring .relation-hover-skill > span {
  display: block;
  margin: 0;
  padding: 5px 7px;
  border-radius: var(--mvu-radius-sm, 8px);
  border: 1px solid rgba(77, 240, 255, 0.1);
  background: rgba(77, 240, 255, 0.05);
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1.3;
  color: var(--white);
  white-space: normal;
  word-break: break-word;
}

.topology-node.interactive-ring .relation-hover-skill {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 5px 6px;
  margin-top: 2px;
}

.topology-node.interactive-ring .relation-hover-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-bottom: 8px;
}

.topology-node.interactive-ring .relation-hover-chip {
  display: inline-flex;
  align-items: center;
  padding: 3px 7px;
  border-radius: var(--mvu-radius-pill, 999px);
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1;
  color: var(--cyan);
  background: rgba(77, 240, 255, 0.08);
  border: 1px solid rgba(77, 240, 255, 0.18);
  max-width: 100%;
  line-height: 1.25;
  white-space: normal;
}

.topology-node.interactive-ring .relation-hover-card .energy-stack {
  margin-top: 8px;
  margin-bottom: 0;
}

.topology-node.interactive-ring .relation-hover-card .energy-headline {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 5px;
}

.topology-node.interactive-ring .relation-hover-card .energy-headline b {
  margin: 0;
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1.3;
  color: var(--text-sub);
  font-weight: 500;
}

.topology-node.interactive-ring .relation-hover-card .energy-headline span {
  display: block;
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1.3;
  color: var(--white);
}

.archive-note:not([data-cabin-plane]):not([data-cabin-flow]) {
  position: relative;
  z-index: 1;
  margin-top: 8px;
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1.45;
