  grid-template-columns: minmax(0, 1fr) 104px;
  gap: 8px;
  align-items: center;
}

.mvu-editor-input,
.mvu-editor-select,
.mvu-editor-textarea {
  width: 100%;
  box-sizing: border-box;
  border-radius: var(--mvu-radius-md, 12px);
  border: 1px solid rgba(120, 220, 255, 0.18);
