    box-shadow 0.2s ease,
    opacity 0.2s ease;
}

.mvu-editor-static {
  width: 100%;
  box-sizing: border-box;
  border-radius: var(--mvu-radius-md, 12px);
  border: 1px solid rgba(120, 220, 255, 0.14);
  background: rgba(5, 14, 24, 0.58);
  color: rgba(239, 249, 255, 0.92);
  padding: 10px 12px;
  font-size: var(--mvu-font-base, 13px);
  line-height: 1.4;
  min-height: 42px;
  display: flex;
  align-items: center;
}

.mvu-editor-input:focus,
.mvu-editor-select:focus,
.mvu-editor-textarea:focus {
  border-color: rgba(0, 229, 255, 0.42);
  box-shadow: 0 0 0 2px rgba(0, 229, 255, 0.12);
}

.mvu-editor-textarea {
