}

/* 普通配置继续单列；原型字段按信息密度分配宽度，避免短值独占整行。 */
.skill-designer-layout .mvu-editor-field-grid {
  grid-template-columns: minmax(0, 1fr);
}

.skill-designer-layout [data-skill-designer-prototype-fields] {
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 12px;
}

.skill-designer-layout [data-skill-designer-prototype-fields] > .mvu-editor-field {
  grid-column: span 6;
}

.skill-designer-layout [data-skill-designer-prototype-fields] > .mvu-editor-field:has([data-skill-designer-prototype-field='目标']),
.skill-designer-layout [data-skill-designer-prototype-fields] > .mvu-editor-field:has([data-skill-designer-prototype-field='生效方式']),
.skill-designer-layout [data-skill-designer-prototype-fields] > .mvu-editor-field:has([data-skill-designer-prototype-field='资源']),
.skill-designer-layout [data-skill-designer-prototype-fields] > .mvu-editor-field:has([data-skill-designer-prototype-field='持续回合']),
.skill-designer-layout [data-skill-designer-prototype-fields] > .mvu-editor-field:has([data-skill-designer-prototype-field='数量']),
.skill-designer-layout [data-skill-designer-prototype-fields] > .mvu-editor-field:has([data-skill-designer-prototype-field='攻击段数']),
.skill-designer-layout [data-skill-designer-prototype-fields] > .mvu-editor-field:has([data-skill-designer-prototype-field='对应等级']) {
  grid-column: span 4;
}

.skill-designer-layout [data-skill-designer-prototype-fields] > .mvu-editor-field:has([data-skill-designer-prototype-field='数值']) {
  grid-column: span 8;
}

.skill-designer-layout [data-skill-designer-prototype-fields] > .mvu-editor-field-wide,
.skill-designer-layout [data-skill-designer-prototype-fields] > .skill-designer-advanced-fields {
  grid-column: 1 / -1;
}

.skill-designer-title-actions {
  display: grid;
  grid-template-columns: minmax(120px, 1fr) max-content max-content;
  align-items: center;
  gap: 6px;
  min-width: 0;
  width: min(46vw, 520px);
  max-width: 100%;
}

.skill-designer-title-switch {
  width: 100%;
  min-width: 0;
  height: 44px;
  box-sizing: border-box;
  border-radius: 999px;
  border: 1px solid rgba(77, 240, 255, 0.28);
  background: rgba(5, 18, 27, 0.92);
  color: rgba(244, 251, 253, 0.96);
  padding: 0 30px 0 12px;
  font-size: max(var(--dc-native-min-font, 0px), 12px);
  line-height: 44px;
  outline: none;
  text-overflow: ellipsis;
  /* 这是切换正在设计哪个技能的主导航控件，必须让人看出可以点开 */
  cursor: pointer;
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, rgba(77, 240, 255, 0.75) 50%),
    linear-gradient(135deg, rgba(77, 240, 255, 0.75) 50%, transparent 50%);
  background-position: right 15px center, right 10px center;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
}

.skill-designer-title-switch:hover {
  border-color: rgba(77, 240, 255, 0.5);
  background-color: rgba(8, 26, 38, 0.96);
}

.skill-designer-title-switch:focus {
  border-color: rgba(77, 240, 255, 0.52);
  box-shadow: 0 0 0 2px rgba(77, 240, 255, 0.12);
}

/* 次要操作（重新读取）：会丢弃未保存的编辑，降到最低视觉权重 */
.skill-designer-title-actions .tag-chip {
  flex: 0 0 auto;
  min-height: 44px;
  padding: 0 12px;
  border-radius: 999px;
  border-color: rgba(164, 221, 234, 0.16);
  background: transparent;
  color: rgba(223, 247, 255, 0.66);
  font-size: max(var(--dc-native-min-font, 0px), 12px);
  font-weight: 400;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
}

.skill-designer-title-actions .tag-chip:hover {
  border-color: rgba(164, 221, 234, 0.3);
  color: rgba(244, 251, 253, 0.92);
}

/* 主操作（保存设计）：实心、加粗、更宽，和次要操作拉开量级 */
.skill-designer-title-actions .tag-chip.live {
  padding: 0 20px;
  border-color: rgba(77, 240, 255, 0.6);
  background: linear-gradient(180deg, rgba(0, 214, 255, 0.34), rgba(0, 152, 214, 0.28));
  color: #f9feff;
  font-weight: 700;
  box-shadow: 0 0 0 1px rgba(77, 240, 255, 0.18) inset, 0 2px 10px rgba(0, 194, 255, 0.18);
}

.skill-designer-title-actions .tag-chip.live:hover {
  border-color: rgba(77, 240, 255, 0.82);
  background: linear-gradient(180deg, rgba(0, 224, 255, 0.42), rgba(0, 162, 224, 0.34));
}

#detailModal .modal-title-wrap:has(.skill-designer-title-actions) {
  grid-template-columns: minmax(0, 1fr) auto;
