  grid-template-columns: minmax(0, 1fr) 14px;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border: 1px solid var(--全息材质线);
  border-radius: 0;
  background: var(--全息材质底);
  color: var(--全息数值文字);
  font: inherit;
  font-size: var(--mvu-font-base, 13px);
  line-height: 18px;
  text-align: left;
