  transition:
    border-color 0.2s,
    background-color 0.2s,
    box-shadow 0.2s;
}

.skill-designer-select-trigger [data-skill-designer-select-value] {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skill-designer-select-trigger i {
  color: color-mix(in srgb, var(--文字弱色) 86%, var(--主题主色));
  font-size: max(var(--dc-native-min-font, 0px), 11px);
  transition: transform 0.18s ease;
}

.skill-designer-select-trigger:hover:not(:disabled) {
  border-color: color-mix(in srgb, var(--边线颜色) 58%, transparent);
