  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skill-designer-delivery-field > .mvu-editor-label {
  padding-right: min(112px, 50%);
}

.skill-designer-inline-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.skill-designer-inline-toggle {
  margin-bottom: 8px;
}

/* 开关加文字状态：原先只有一个 18px 空方块，看不出当前是开还是关
   （对应 UX 准则 Color Only：不要只靠颜色/形状传达状态） */
.skill-designer-check-toggle {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
  min-height: 18px;
  cursor: pointer;
}

.skill-designer-check-toggle::after {
  content: '关';
  color: rgba(223, 247, 255, 0.5);
  font-size: max(var(--dc-native-min-font, 0px), 11px);
  letter-spacing: 0.05em;
}

.skill-designer-check-toggle:has(input:checked)::after {
  content: '开';
  color: rgba(77, 240, 255, 0.92);
}

.skill-designer-check-toggle input {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
}

.skill-designer-check-toggle span {
  width: 18px;
  height: 18px;
  box-sizing: border-box;
  border-radius: var(--mvu-radius-sm, 8px);
  border: 1px solid rgba(120, 220, 255, 0.28);
  background: rgba(5, 14, 24, 0.78);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.skill-designer-check-toggle input:checked + span {
  border-color: rgba(92, 230, 255, 0.68);
  background: rgba(44, 190, 220, 0.3);
}

.skill-designer-check-toggle input:checked + span::after {
  content: '';
  position: absolute;
  left: 6px;
  top: 3px;
  width: 4px;
  height: 8px;
  border: solid #f2fdff;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}

.skill-designer-shell .mvu-editor-textarea {
  min-height: 138px;
}

.skill-designer-shell .mvu-editor-input::placeholder,
.skill-designer-shell .mvu-editor-textarea::placeholder {
  color: rgba(182, 206, 214, 0.8);
}

.skill-designer-param-label {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.skill-designer-param-label i {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  color: rgba(184, 215, 224, 0.74);
  font-style: normal;
  font-size: var(--mvu-font-sm, 12px);
  font-weight: 500;
  line-height: 1.2;
  text-align: right;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skill-designer-state-summary {
  display: block;
  min-height: 1.2em;
  margin-top: 4px;
  color: rgba(209, 250, 255, 0.78);
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1.3;
}

.skill-designer-time-parts {
  min-width: 0;
}

.skill-designer-time-parts-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.skill-designer-time-parts-grid label {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 22px;
  align-items: center;
  min-width: 0;
}

.skill-designer-time-parts-grid span {
  grid-column: 2;
  grid-row: 1;
  justify-self: center;
  color: rgba(184, 215, 224, 0.74);
  font-size: var(--mvu-font-sm, 12px);
  pointer-events: none;
}

.skill-designer-time-parts-grid .mvu-editor-input {
  grid-column: 1 / -1;
  grid-row: 1;
  padding-right: 28px;
}

.skill-designer-shell .mvu-editor-input:focus,
.skill-designer-shell .mvu-editor-select:focus,
.skill-designer-shell .mvu-editor-textarea:focus {
  border-color: color-mix(in srgb, var(--边线颜色) 40%, transparent);
  box-shadow:
    0 0 10px color-mix(in srgb, var(--主题主色) 18%, transparent),
    inset 0 0 5px color-mix(in srgb, var(--主题主色) 8%, transparent);
  outline: none;
}

.skill-designer-filter-select {
  min-width: 0;
  position: relative;
}

.skill-designer-filter-select--wide {
  grid-column: 1 / -1;
}

.skill-designer-filter-select-box {
  position: relative;
}

.skill-designer-filter-select:has(.skill-designer-filter-select-box[open]) {
  z-index: 20;
}

.skill-designer-filter-select-box summary {
  min-height: 40px;
  display: flex;
  align-items: center;
  min-width: 0;
  padding: 10px 14px;
  border: 1px solid var(--全息材质线);
  border-radius: 0;
  background: var(--全息材质底);
  color: var(--全息数值文字);
  font-size: var(--mvu-font-base, 13px);
  line-height: 18px;
  cursor: pointer;
  list-style: none;
  transition:
    border-color 0.2s,
    background-color 0.2s,
    box-shadow 0.2s;
}

.skill-designer-filter-select-box summary::-webkit-details-marker {
  display: none;
}

.skill-designer-filter-select-box summary::after {
  content: '⌄';
  margin-left: auto;
  color: color-mix(in srgb, var(--主题主色) 70%, transparent);
}

.skill-designer-filter-select-box summary:hover {
  border-color: color-mix(in srgb, var(--边线颜色) 58%, transparent);
  background: color-mix(in srgb, var(--全息材质底) 92%, var(--主题主色) 8%);
}

.skill-designer-filter-select-box summary:focus-visible,
.skill-designer-filter-select-box[open] summary {
  border-color: color-mix(in srgb, var(--边线颜色) 52%, transparent);
  box-shadow:
    0 0 0 2px color-mix(in srgb, var(--主题主色) 14%, transparent),
    inset 0 0 5px color-mix(in srgb, var(--主题主色) 8%, transparent);
  outline: none;
}

.skill-designer-filter-select-box[open] summary::after {
  content: '⌃';
}

.skill-designer-filter-select-box summary span {
  min-width: 0;
  overflow-wrap: anywhere;
  white-space: normal;
}

.skill-designer-filter-options {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  z-index: 30;
  max-height: 176px;
  overflow: auto;
  margin-top: 0;
  border: 1px solid rgba(120, 220, 255, 0.12);
  border-radius: var(--mvu-radius-lg, 16px);
  background: rgba(4, 14, 22, 0.92);
  box-shadow:
    0 18px 34px rgba(0, 0, 0, 0.38),
    0 0 0 1px color-mix(in srgb, var(--边线颜色) 10%, transparent);
}

.skill-designer-filter-option {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 34px;
  padding: 8px 12px;
  color: rgba(232, 244, 248, 0.92);
  cursor: pointer;
}

.skill-designer-filter-option + .skill-designer-filter-option {
  border-top: 1px solid rgba(120, 220, 255, 0.08);
}

.skill-designer-filter-option:hover {
  background: rgba(85, 210, 230, 0.08);
}

.skill-designer-filter-option input {
  width: 14px;
  height: 14px;
  accent-color: #65d9ef;
}

.skill-designer-chip-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.skill-designer-fusion-mode-grid {
  grid-template-columns: minmax(180px, 0.42fr);
}

.skill-designer-fusion-participant-list {
  display: grid;
  gap: 10px;
}

.skill-designer-fusion-participant-row {
  display: grid;
  grid-template-columns: minmax(168px, 0.9fr) minmax(168px, 1fr) auto;
  gap: 10px;
  align-items: end;
  padding: 10px;
  border-radius: var(--mvu-radius-lg, 16px);
  border: 1px solid rgba(165, 214, 228, 0.11);
  background: rgba(5, 14, 24, 0.42);
}

.skill-designer-fusion-row-actions {
  display: flex;
  align-items: end;
  min-height: 44px;
}

.skill-designer-fusion-row-actions .tag-chip {
  min-height: 40px;
  border-radius: var(--mvu-radius-md, 12px);
  white-space: nowrap;
}

:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) button.tag-chip,
:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) .tag-chip.clickable,
:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) .clickable {
  cursor: pointer;
  transition:
    transform 180ms ease,
    background 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease,
    opacity 180ms ease;
}

:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) button.tag-chip:hover,
:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) .tag-chip.clickable:hover,
:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) .clickable:hover {
  border-color: rgba(77, 240, 255, 0.24);
  background: rgba(77, 240, 255, 0.09);
}

:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) button.tag-chip:active,
:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) .tag-chip.clickable:active,
:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) .clickable:active {
  transform: translateY(1px);
}

:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) .tag-chip.is-busy,
:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) .tag-chip.is-short-lock {
  opacity: 0.58;
  pointer-events: none;
}

.skill-designer-fusion-actions {
  margin-left: 0;
  justify-content: flex-start;
}

.skill-designer-fusion-actions[hidden]:not([data-cabin-plane]):not([data-cabin-flow]) {
  display: none !important;
}

.skill-designer-check-chip {
  position: relative;
  cursor: pointer;
  user-select: none;
}

.skill-designer-check-chip input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.skill-designer-check-chip span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 32px;
  padding: 7px 12px;
  border-radius: var(--mvu-radius-pill, 999px);
  border: 1px solid rgba(165, 214, 228, 0.14);
  background: rgba(186, 223, 235, 0.06);
  color: rgba(223, 236, 241, 0.8);
  font-size: var(--mvu-font-sm, 12px);
  line-height: 1.2;
  transition:
    border-color 0.18s ease,
    background 0.18s ease,
    color 0.18s ease,
    box-shadow 0.18s ease;
}

.skill-designer-check-chip.active span {
  border-color: rgba(123, 220, 239, 0.28);
  background: rgba(89, 186, 212, 0.16);
  color: rgba(245, 249, 250, 0.98);
  box-shadow: 0 0 0 1px rgba(123, 220, 239, 0.1) inset;
}

.skill-designer-check-chip.recommended span {
  border-color: rgba(198, 224, 232, 0.2);
  background: rgba(227, 239, 244, 0.08);
}

.skill-designer-preview-stack {
  display: grid;
  gap: 10px;
}

.skill-designer-summary-list {
  gap: 10px;
}

.skill-designer-summary-row {
  display: grid;
  gap: 5px;
  padding: 10px 14px;
  border-radius: 0;
  border: none;
  border-left: 2px solid color-mix(in srgb, var(--边线颜色) 46%, transparent);
  background: linear-gradient(90deg, color-mix(in srgb, var(--主题主色) 10%, transparent), transparent);
  position: relative;
}

/* 最终摘要是右栏唯一一段人话，上浮到首屏并给出主标题量级 */
.skill-designer-summary-row--headline {
  border-left-color: color-mix(in srgb, var(--主题主色) 72%, transparent);
  background: linear-gradient(90deg, color-mix(in srgb, var(--主题主色) 20%, transparent), transparent);
}

.skill-designer-summary-row--headline > span {
  font-size: max(var(--dc-native-min-font, 0px), 13px);
  line-height: 1.5;
}

/* COST 明细是结算中间量，默认折叠；玩家要的是「够不够」不是系数 */
.skill-designer-cost-fold > summary {
  cursor: pointer;
  font-size: max(var(--dc-native-min-font, 0px), 12px);
  color: rgba(223, 247, 255, 0.72);
  list-style: none;
}

.skill-designer-cost-fold > summary::-webkit-details-marker {
  display: none;
}

.skill-designer-cost-fold > summary::before {
  content: '▸ ';
  color: color-mix(in srgb, var(--主题主色) 80%, transparent);
}

.skill-designer-cost-fold[open] > summary::before {
  content: '▾ ';
}

.skill-designer-summary-row em {
  font-style: normal;
  font-size: var(--mvu-font-xs, 10px);
  font-family: monospace;
  text-transform: uppercase;
  line-height: 1.35;
  color: var(--全息标签文字);
  letter-spacing: 0.1em;
}

.skill-designer-summary-row span {
  display: block;
  font-size: var(--mvu-font-md, 14px);
  line-height: 1.55;
  color: #fff;
  text-shadow: var(--全息数值字影);
  white-space: normal;
  word-break: break-word;
}

.skill-designer-attribute-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(60px, 100%), 1fr));
  gap: 8px 10px;
  min-width: 0;
}

.skill-designer-attribute-cell {
  display: grid;
  gap: 2px;
  align-content: start;
  min-width: 0;
  padding: 0;
  color: #fff;
  text-shadow: var(--全息数值字影);
}

.skill-designer-attribute-cell b {
  font-size: var(--mvu-font-sm, 12px);
  font-weight: 500;
  color: var(--全息标签文字);
}

.skill-designer-attribute-cell strong {
  min-width: 0;
  font-size: var(--mvu-font-md, 14px);
  font-weight: 700;
  color: #fff;
  line-height: 1.22;
  overflow-wrap: anywhere;
  word-break: break-word;
  white-space: normal;
}

.skill-designer-trial-card > div {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.skill-designer-cost-panel {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.skill-designer-trial-row {
  display: grid;
  grid-template-columns: minmax(112px, 1fr) minmax(64px, auto);
  gap: 8px;
  align-items: center;
  min-height: 32px;
  padding: 4px 0;
}

.skill-designer-trial-row em {
  position: relative;
  min-width: 0;
  color: var(--全息标签文字);
  overflow-wrap: anywhere;
  white-space: normal;
  line-height: 1.35;
}

.skill-designer-trial-row span {
  min-width: 64px;
  color: var(--全息数值文字);
  font-weight: bold;
  text-align: right;
  white-space: nowrap;
}

.skill-designer-cost-help {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  margin-left: 4px;
  padding: 0;
  border: 1px solid color-mix(in srgb, var(--边线颜色) 40%, transparent);
  border-radius: 50%;
  background: color-mix(in srgb, var(--主题主色) 8%, transparent);
  color: var(--全息标签文字);
  font: 700 10px/1 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  vertical-align: 1px;
  cursor: help;
}

.skill-designer-cost-help::after {
  content: attr(data-cost-tip);
  position: absolute;
  z-index: 20;
  left: 50%;
  bottom: calc(100% + 8px);
  width: min(220px, 62vw);
  padding: 7px 9px;
  border: 1px solid color-mix(in srgb, var(--边线颜色) 24%, transparent);
  background: rgba(8, 18, 20, 0.96);
  color: rgba(226, 252, 255, 0.92);
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.34);
  font: 500 11px/1.45 "Microsoft YaHei", sans-serif;
  text-align: left;
  white-space: normal;
  overflow-wrap: break-word;
  transform: translate(-50%, 4px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.16s ease, transform 0.16s ease;
}

.skill-designer-cost-help:hover::after,
.skill-designer-cost-help:focus-visible::after {
  opacity: 1;
  transform: translate(-50%, 0);
}

.skill-designer-cost-block {
  display: grid;
  gap: 6px;
  min-width: 0;
  padding: 0 0 6px;
  border-bottom: 1px dashed color-mix(in srgb, var(--边线颜色) 24%, transparent);
}

.skill-designer-cost-block > summary {
  list-style: none;
  cursor: pointer;
}

.skill-designer-cost-block > summary::-webkit-details-marker {
  display: none;
}

.skill-designer-cost-block > .skill-designer-trial-row {
  padding-bottom: 0;
}

.skill-designer-cost-block > summary.skill-designer-trial-row {
  padding-bottom: 0;
}

.skill-designer-cost-block > summary.skill-designer-trial-row em {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.skill-designer-cost-block > summary.skill-designer-trial-row em::before {
  content: "▾";
  color: var(--全息标签文字);
  font-size: var(--mvu-font-xs, 10px);
