}

.mvu-spirit-archive-shell .soul-ring-terminal-meta .mvu-inline-editable {
  display: inline;
}

.mvu-spirit-archive-shell .soul-ring-lane {
  justify-content: center;
  align-items: center;
  gap: 0;
  margin-top: 0;
  flex-wrap: nowrap;
  overflow: visible;
}

.mvu-spirit-archive-shell .soul-ring-lane .ring {
  width: 33px;
  height: 33px;
  flex: 0 0 33px;
  font-size: max(var(--dc-native-min-font, 0px), 9px);
