}

.mvu-spirit-archive-shell .soul-ring-lane .ring::before {
  inset: -2px;
  border-style: dashed;
  opacity: 0.48;
}

.mvu-spirit-archive-shell .soul-ring-lane .ring::after {
  inset: 5px;
  box-shadow:
    0 0 7px var(--ring-glow, currentColor),
    inset 0 0 6px color-mix(in oklab, currentColor 38%, white 22%),
    inset 0 0 0 1px var(--ring-edge, transparent);
}

.mvu-spirit-archive-shell .ring-gold,
.mvu-spirit-archive-shell .ring-orangegold,
.mvu-spirit-archive-shell .ring-yellow {
  --ring-glow: rgba(255, 215, 0, 0.38);
}

.mvu-spirit-archive-shell .ring-black {
  --ring-glow: rgba(108, 76, 161, 0.28);
}

.mvu-spirit-archive-shell .ring-purple {
  --ring-glow: rgba(217, 70, 239, 0.3);
}

.mvu-spirit-archive-shell .ring-red {
  --ring-glow: rgba(255, 77, 122, 0.32);
}

.mvu-spirit-archive-shell .soul-ring-empty {
  min-height: 0;
  padding: 5px 0 0;
  color: var(--文字弱色);
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1.4;
  letter-spacing: 0.03em;
  border: 0;
  background: transparent;
}

.mvu-soul-ring-scanfield {
  --ring-anchor-rail-width: 54px;
  --ring-anchor-hit-height: 24px;
  --ring-anchor-line-width: 78px;
  --ring-anchor-node-size: 16px;
  position: relative;
  display: grid;
  place-items: center;
  width: var(--ring-stage-width, 214px);
  min-width: calc(var(--ring-stage-width, 214px) + var(--ring-anchor-rail-width));
  height: var(--ring-stage-height, 160px);
  min-height: var(--ring-stage-height, 160px);
  isolation: isolate;
  overflow: visible;
}

.mvu-soul-ring-scanfield > .mvu-soul-ring-stage {
  position: relative;
  z-index: 1;
}

.mvu-soul-ring-anchor-rail {
  position: absolute;
  z-index: 5;
  top: 0;
  right: 0;
  width: var(--ring-anchor-rail-width);
  height: 100%;
  pointer-events: none;
}

.mvu-soul-ring-anchor {
  --ring-anchor-color: color-mix(in srgb, var(--c-acc, #79f7ff) 58%, var(--mvu-holo-main, #48f0ff));
  --ring-anchor-bloom: var(--g-bloom, var(--ring-anchor-color));
  position: absolute;
  right: 0;
  top: var(--anchor-y, 50%);
  display: grid;
  grid-template-columns: minmax(34px, var(--ring-anchor-line-width)) var(--ring-anchor-node-size);
  align-items: center;
  width: calc(var(--ring-anchor-line-width) + var(--ring-anchor-node-size) + 8px);
  height: var(--ring-anchor-hit-height);
  padding: 0 3px 0 0;
  border: 0;
  background: transparent;
  color: var(--ring-anchor-color);
  cursor: crosshair;
  pointer-events: auto;
  transform: translateY(-50%);
  transform-origin: right center;
  opacity: 0.64;
}

.mvu-soul-ring-anchor:focus-visible {
  outline: 1px solid color-mix(in srgb, currentColor 60%, transparent);
  outline-offset: 2px;
}

.mvu-soul-ring-leader {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.mvu-soul-ring-leader i,
.mvu-soul-ring-leader b {
  position: absolute;
  display: block;
  height: 1px;
  border-radius: 999px;
  background:
    linear-gradient(90deg, transparent, color-mix(in srgb, var(--ring-anchor-color) 64%, transparent), transparent),
    repeating-linear-gradient(90deg, transparent 0 7px, currentColor 7px 10px, transparent 10px 20px);
  background-size: 100% 100%, 44px 100%;
  opacity: 0.24;
  box-shadow: 0 0 5px color-mix(in srgb, var(--ring-anchor-bloom) 16%, transparent);
}

.mvu-soul-ring-leader i {
  right: 20px;
  top: 50%;
  width: calc(100% - 18px);
  transform: translateY(-50%) skewY(calc((0.5 - var(--anchor-ratio, 0.5)) * 18deg));
  transform-origin: right center;
}

.mvu-soul-ring-leader b {
  right: 0;
  top: 50%;
  width: 22px;
  transform: translateY(-50%);
}

.mvu-soul-ring-anchor-node {
  position: relative;
  display: grid;
  place-items: center;
  width: var(--ring-anchor-node-size);
  height: var(--ring-anchor-node-size);
  color: currentColor;
  font-size: max(var(--dc-native-min-font, 0px), 14px);
  line-height: 1;
  text-shadow: 0 0 8px color-mix(in srgb, currentColor 46%, transparent);
  filter: saturate(0.85) brightness(0.82);
  pointer-events: none;
}

.mvu-soul-ring-anchor:hover,
.mvu-soul-ring-anchor:focus-visible,
.mvu-soul-ring-anchor.mvu-soul-ring-anchor-active {
  opacity: 1;
  color: color-mix(in srgb, var(--ring-anchor-color) 64%, var(--mvu-holo-high, #f7fdff));
}

.mvu-soul-ring-anchor:hover .mvu-soul-ring-leader i,
.mvu-soul-ring-anchor:hover .mvu-soul-ring-leader b,
.mvu-soul-ring-anchor:focus-visible .mvu-soul-ring-leader i,
.mvu-soul-ring-anchor:focus-visible .mvu-soul-ring-leader b,
.mvu-soul-ring-anchor.mvu-soul-ring-anchor-active .mvu-soul-ring-leader i,
.mvu-soul-ring-anchor.mvu-soul-ring-anchor-active .mvu-soul-ring-leader b {
  opacity: 0.96;
  animation: soul-ring-anchor-flow 0.62s linear infinite;
  box-shadow:
    0 0 6px currentColor,
    0 0 14px color-mix(in srgb, var(--ring-anchor-bloom) 34%, transparent);
}

.mvu-soul-ring-anchor:hover .mvu-soul-ring-anchor-node,
.mvu-soul-ring-anchor:focus-visible .mvu-soul-ring-anchor-node,
.mvu-soul-ring-anchor.mvu-soul-ring-anchor-active .mvu-soul-ring-anchor-node {
  filter: saturate(1.2) brightness(1.35);
  text-shadow:
    0 0 8px currentColor,
    0 0 18px color-mix(in srgb, var(--ring-anchor-bloom) 56%, transparent);
}

.mvu-soul-ring-slot.mvu-hover-floating-active {
  z-index: calc(var(--ring-total, 10) + 10);
}

.mvu-soul-ring-slot.mvu-hover-floating-active .mvu-soul-ring-svg {
  filter:
    brightness(1.7)
    saturate(1.24)
    drop-shadow(0 0 10px color-mix(in srgb, var(--c-acc, #79f7ff) 62%, transparent))
    drop-shadow(0 0 22px color-mix(in srgb, var(--g-bloom, #48f0ff) 34%, transparent));
}

.mvu-soul-ring-slot.mvu-hover-floating-active .mvu-soul-ring-svg .spin-cw {
  animation-duration: 9s;
}

.mvu-soul-ring-slot.mvu-hover-floating-active .mvu-soul-ring-svg .spin-ccw {
  animation-duration: 7s;
}

.ring-hover-card.soul-ring-tooltip {
  width: min(296px, calc(100vw - 32px));
  max-width: min(296px, calc(100vw - 32px));
  max-height: min(260px, 60svh);
  padding: 8px 9px;
  border-radius: 0;
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
  border-color: color-mix(in srgb, var(--边线颜色) 60%, transparent);
  background:
    repeating-linear-gradient(0deg, color-mix(in srgb, var(--主题主色) 5%, transparent) 0 1px, transparent 1px 16px),
