  box-shadow: none;
}

.ring-hover-card.soul-ring-tooltip .ring-hover-title {
  margin-bottom: 3px;
  font-size: var(--mvu-font-sm, 12px);
  color: var(--文字主色);
}

.ring-hover-card.soul-ring-tooltip .ring-hover-desc {
  margin-bottom: 7px;
  padding-bottom: 6px;
  border-bottom: 1px dashed color-mix(in srgb, var(--边线颜色) 20%, transparent);
  color: var(--文字弱色);
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1.35;
}

.ring-hover-card.soul-ring-tooltip .ring-hover-meta {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 3px 8px;
  margin-bottom: 6px;
}

.ring-hover-card.soul-ring-tooltip .ring-hover-meta-row {
  min-width: 0;
  padding: 0;
  border-radius: 0;
  border: 0;
  background: transparent;
  flex-direction: row;
  justify-content: flex-start;
  gap: 5px;
}

.ring-hover-card.soul-ring-tooltip .ring-hover-meta-row em,
.ring-hover-card.soul-ring-tooltip .ring-hover-meta-row strong {
  text-align: left;
  max-width: none;
}

.ring-hover-card.soul-ring-tooltip .ring-hover-meta-row em {
  flex: 0 0 auto;
}

.ring-hover-card.soul-ring-tooltip .ring-hover-copy {
  margin-bottom: 6px;
  padding-top: 5px;
  border-top: 1px dashed color-mix(in srgb, var(--边线颜色) 16%, transparent);
}

.ring-hover-card.soul-ring-tooltip .ring-hover-copy:last-child {
  margin-bottom: 0;
}

.ring-hover-card.soul-ring-tooltip .ring-hover-copy em {
  color: color-mix(in srgb, var(--文字弱色) 88%, transparent);
}

.ring-hover-card.soul-ring-tooltip .ring-hover-copy span {
  color: var(--文字主色);
