.spirit-head-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}

.soul-meta {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
  margin-top: 8px;
}

.seal-column {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 6px;
  margin-top: 8px;
}

.seal-node {
  border-radius: var(--mvu-radius-md, 12px);
  padding: 8px 9px;
  border: 1px solid var(--mvu-color-panel-muted, rgba(255, 255, 255, 0.05));
