body.mvu-layout-holo #mvu-unified-mount .mvu-unified-frame {
  position: relative;
  box-sizing: border-box;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  gap: 0;
  width: 100%;
  height: var(--mvu-hud-frame-height, 620px);
  min-height: 0;
  max-height: var(--mvu-hud-frame-height, 620px);
  overflow: hidden;
  isolation: isolate;
  border: 1px solid #465963;
  border-radius: 18px 18px 26px 26px;
  clip-path: none;
  background:
    #040b10;
  box-shadow: var(--主窗体阴影);
  backdrop-filter: var(--虚化强度);
  -webkit-backdrop-filter: var(--虚化强度);
  color: var(--mvu-holo-text);
  font-family: var(--主题字体);
  font-weight: var(--主题字重);
  perspective: 1200px;
  pointer-events: auto;
  padding: 13px 20px 17px;
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-frame::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  border-radius: inherit;
  background: var(--面板光层);
  opacity: 1;
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-frame > :not(.mvu-cabin-structure) {
  position: relative;
  z-index: 1;
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-shell {
  position: relative;
  width: 100%;
  min-width: 0;
  overflow: visible;
}

