}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-frame.is-holo-animation-paused {
  --mvu-holo-loop-play-state: paused;
}

body.mvu-layout-holo #mvu-unified-mount .mvu-holo-theme-btn {
  appearance: none;
  -webkit-appearance: none;
  display: inline-grid;
  place-items: center;
  width: 64px;
  min-width: 64px;
  min-height: 25px;
  padding: 2px 7px;
  border: 1px solid var(--边线颜色);
  border-radius: 999px;
  background: var(--二级实体材质);
  color: var(--mvu-holo-text);
  font-size: max(var(--dc-native-min-font, 0px), 10px);
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  box-shadow: 0 0 10px color-mix(in srgb, var(--主题主色) 12%, transparent);
}

body.mvu-layout-holo #mvu-unified-mount .mvu-holo-theme-btn[aria-pressed='true'] {
  border-color: var(--主题主色);
  color: var(--mvu-holo-main);
  box-shadow: 0 0 14px color-mix(in srgb, var(--主题主色) 34%, transparent);
}

body.mvu-layout-holo #mvu-unified-mount .mvu-holo-theme-btn:hover,
body.mvu-layout-holo #mvu-unified-mount .mvu-holo-theme-btn:focus-visible {
  color: var(--mvu-holo-high);
  outline: none;
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-shell,
body.mvu-layout-holo #mvu-unified-mount .mvu-unified-panel-host {
  position: relative;
  box-sizing: border-box;
  min-width: 0;
  width: 100%;
  padding-left: 0;
  overflow: visible;
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-toolbar {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 34px;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding: 4px 10px 8px;
  background: transparent;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  box-shadow: none;
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-toolbar-main {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(230px, 1fr) minmax(0, 1.4fr);
  align-items: center;
  gap: 16px;
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-overview-bar {
  display: grid;
  grid-template-columns: minmax(216px, 0.76fr) minmax(330px, 1.24fr);
  grid-template-rows: auto;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-status-strip {
  display: grid;
  grid-template-columns: minmax(104px, max-content) minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  min-width: 0;
  min-height: 30px;
  padding: 2px 4px;
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-character-switch {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 26px;
  padding: 2px 8px 2px 4px;
  border-radius: 6px;
  border: 1px solid color-mix(in srgb, var(--主题主色) 38%, transparent);
  background: color-mix(in srgb, var(--暗场卡片) 68%, transparent);
  box-shadow: inset 0 0 10px color-mix(in srgb, var(--主题主色) 10%, transparent), 0 2px 6px rgba(0, 0, 0, 0.25);
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-character-switch:hover {
  border-color: var(--主题主色);
  background: color-mix(in srgb, var(--主题主色) 18%, transparent);
  box-shadow: 0 0 12px color-mix(in srgb, var(--主题主色) 32%, transparent), inset 0 0 12px color-mix(in srgb, var(--主题主色) 18%, transparent);
  transform: translateY(-1px);
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-character-switch .char-emblem {
  display: inline-grid;
  place-items: center;
  width: 19px;
  height: 19px;
  border-radius: 4px;
  border: 1px solid color-mix(in srgb, var(--主题高光) 55%, transparent);
  background: color-mix(in srgb, var(--主题主色) 24%, transparent);
  color: var(--主题高光);
  font-size: max(var(--dc-native-min-font, 0px), 10.5px);
  font-weight: 850;
  box-shadow: 0 0 6px color-mix(in srgb, var(--主题主色) 32%, transparent);
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-character-switch .char-name {
  max-width: 110px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--文字主色);
  font-size: max(var(--dc-native-min-font, 0px), 12.5px);
  font-weight: 850;
  line-height: 1;
  letter-spacing: 0.4px;
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-header-loc {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
  padding-left: 9px;
  border-left: 1px solid color-mix(in srgb, var(--边线颜色) 36%, transparent);
  gap: 2px;
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-header-loc .mvu-header-time {
  color: var(--主题高光);
  font: 800 11px/1.15 var(--font-mono, "Cascadia Code", Consolas, monospace);
  letter-spacing: 0.3px;
  text-shadow: 0 0 8px color-mix(in srgb, var(--主题高光) 26%, transparent);
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-header-loc .mvu-header-location {
  color: var(--文字弱色);
  font-size: max(var(--dc-native-min-font, 0px), 10.5px);
  line-height: 1.15;
  opacity: 0.92;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-detail-title {
  min-width: 0;
  overflow: hidden;
  color: var(--mvu-holo-high);
  font-size: 18px;
  font-weight: 600;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
  letter-spacing: 2px;
  font-family: "Microsoft YaHei UI", sans-serif;
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-tab-row {
  display: flex;
  align-items: center;
  justify-content: stretch;
  gap: 4px;
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none;
  padding: 4px 12px;
  border-radius: 5px 5px 16px 16px;
  background: linear-gradient(180deg, #253039, #080f16 50%, #18212a);
  border: 1px solid #7c929c;
  box-shadow: 0 3px 0 #02080c, inset 0 1px #b4c7cf55;
  grid-row: 4;
  width: 78%;
  justify-self: center;
  min-height: 37px;
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-tab-row::-webkit-scrollbar {
  width: 0;
  height: 0;
  display: none;
}

