.dc-host{--dc-ink:#e6edf3;--dc-muted:#a8bacb;--dc-gold:#e5c482;--dc-silver:#c7dce9;--dc-line:#8eacc13b;--dc-dark:#090f18;--dc-display:"Microsoft YaHei UI","Microsoft YaHei",sans-serif;--dc-body:"Microsoft YaHei UI","Microsoft YaHei",sans-serif;--dc-number:"Segoe UI","Microsoft YaHei UI",sans-serif;box-sizing:border-box;width:100%;min-width:0;color:var(--dc-ink);font:16px/1.65 var(--dc-body);background:var(--dc-dark);isolation:isolate}
