  }
  18%,
  62% {
    opacity: 0.44;
  }
  100% {
    opacity: 0;
    transform: translate3d(68%, 0, 0) skewX(-15deg);
  }
}

@keyframes 金龙雷达脉冲 {
  0%,
  100% {
    opacity: 0.9;
    transform: scale(0.996);
  }
  50% {
    opacity: 1;
    transform: scale(1.018);
  }
}

@keyframes 金龙龙脉脉冲 {
  0%,
  100% {
    opacity: 0.5;
    transform: translate(-50%, -50%) scaleY(0.98);
  }
  50% {
    opacity: 0.72;
    transform: translate(-50%, -50%) scaleY(1.025);
  }
}

@keyframes 金龙热浪脉冲 {
  0%,
  100% {
    opacity: 0.2;
    transform: translate(-50%, -50%) scale(0.98);
  }
  50% {
    opacity: 0.38;
    transform: translate(-50%, -50%) scale(1.02);
  }
}

