  0%,
  100% {
    background-position: center, center, 0 50%;
    opacity: 0.52;
  }
  50% {
    background-position: center, center, 100% 50%;
    opacity: 0.72;
  }
}

@keyframes 魂环舱导轨流 {
  0% {
    background-position: center, 0 100%;
    opacity: var(--魂环舱导轨流低透明度, 0.46);
  }
  50% {
    opacity: var(--魂环舱导轨流高透明度, 0.78);
  }
  100% {
    background-position: center, 0 0;
    opacity: var(--魂环舱导轨流低透明度, 0.46);
  }
}

