   ========================================================================= */
#detailModal.mvu-modal-display-unified {
  inset: 0;
  width: 100vw;
  min-height: 100svh;
  height: 100svh;
  box-sizing: border-box;
  align-items: center;
  justify-content: center;
  padding: 18px 24px calc(18px + env(safe-area-inset-bottom, 0px));
  --mvu-dossier-panel: transparent;
  --mvu-dossier-panel-soft: transparent;
  --mvu-dossier-line: var(--全息材质弱线);
  --mvu-dossier-line-strong: var(--全息材质线);
  --mvu-dossier-label: var(--全息标签文字);
  --mvu-dossier-value: var(--全息数值文字);
  --mvu-dossier-muted: var(--全息标签文字);
}

#detailModal.mvu-modal-display-unified .mvu-modal-panel:not([data-cabin-plane]):not([data-cabin-flow]),
#detailModal.mvu-modal-display-unified .mvu-modal-panel.archive-mode:not([data-cabin-plane]):not([data-cabin-flow]) {
  width: min(1120px, calc(100vw - 48px)) !important;
  max-width: min(1120px, calc(100vw - 48px)) !important;
  min-height: 0 !important;
  max-height: min(86svh, 920px) !important;
  border: 1px solid var(--边线颜色);
  border-radius: var(--投影圆角);
  background:
    var(--详情环境光),
    var(--主面板材质),
    var(--背景细纹),
    var(--主窗体底色);
  box-shadow: var(--主窗体阴影);
  overflow: hidden;
}

#detailModal.mvu-modal-display-unified .mvu-modal-panel::before {
  content: none;
  display: none;
  background: transparent;
  opacity: 0;
  animation: none;
}

#detailModal.mvu-modal-display-unified .mvu-modal-panel::after {
  content: none;
  display: none;
  background: transparent;
  opacity: 0;
}

#detailModal.mvu-modal-display-unified .mvu-modal-panel > * {
  position: relative;
  z-index: 1;
