@keyframes 战斗介质漂移 {
  0% { background-position: 0 0, 0 0, center; }
  100% { background-position: 31px 31px, -43px 43px, center; }
}

@keyframes 战斗警报展开 {
  0% { opacity: 0; transform: translateY(12px) scaleY(0.4); }
  100% { opacity: 1; transform: translateY(0) scaleY(1); }
}

@keyframes 战斗警报呼吸 {
  0% { opacity: 0.74; transform: translateY(0); }
  100% { opacity: 1; transform: translateY(-1px); }
}

@keyframes 战斗资源扫光 {
  0% { background-position: 160% 0; }
  100% { background-position: -60% 0; }
}

@keyframes 战斗资源临界 {
  0% { opacity: 0.32; }
  100% { opacity: 0.9; }
}

@media (max-width: 760px) {
  body.mvu-layout-holo #mvu-unified-mount #mvu-battle-inline-host .battle-shell:not([data-cabin-plane]):not([data-cabin-flow]),
  #detailModal #mvu-battle-inline-host .battle-shell:not([data-cabin-plane]):not([data-cabin-flow]) {
    grid-template-rows: auto auto minmax(0, 1fr);
    padding: 10px;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    touch-action: pan-y;
    -webkit-overflow-scrolling: touch;
  }

  body.mvu-layout-holo #mvu-unified-mount #mvu-battle-inline-host .battle-control-bar:not([data-cabin-plane]):not([data-cabin-flow]),
  #detailModal #mvu-battle-inline-host .battle-control-bar:not([data-cabin-plane]):not([data-cabin-flow]),
  body.mvu-layout-holo #mvu-unified-mount #mvu-battle-inline-host .battle-hud-layer:not([data-cabin-plane]):not([data-cabin-flow]),
  #detailModal #mvu-battle-inline-host .battle-hud-layer:not([data-cabin-plane]):not([data-cabin-flow]),
  body.mvu-layout-holo #mvu-unified-mount #mvu-battle-inline-host .battle-dashboard-layer:not([data-cabin-plane]):not([data-cabin-flow]),
  #detailModal #mvu-battle-inline-host .battle-dashboard-layer:not([data-cabin-plane]):not([data-cabin-flow]),
  body.mvu-layout-holo #mvu-unified-mount #mvu-battle-inline-host .bar-stack,
  #detailModal #mvu-battle-inline-host .bar-stack {
    grid-template-columns: minmax(0, 1fr);
  }

  body.mvu-layout-holo #mvu-unified-mount #mvu-battle-inline-host .resource-bar,
  #detailModal #mvu-battle-inline-host .resource-bar {
    grid-template-columns: 38px minmax(0, 1fr);
  }

  body.mvu-layout-holo #mvu-unified-mount #mvu-battle-inline-host .stats-grid,
  #detailModal #mvu-battle-inline-host .stats-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  body.mvu-layout-holo #mvu-unified-mount #mvu-battle-inline-host .battle-team-strip,
  #detailModal #mvu-battle-inline-host .battle-team-strip {
    grid-auto-flow: column;
    grid-auto-columns: minmax(96px, 1fr);
  }

  body.mvu-layout-holo #mvu-unified-mount .mvu-battle-return-entry {
    grid-template-columns: minmax(0, 1fr);
    gap: 4px;
  }

  body.mvu-layout-holo #mvu-unified-mount .mvu-battle-return-entry span:last-child {
    text-align: left;
  }
}

@media (prefers-reduced-motion: reduce) {
  body.mvu-layout-holo #mvu-unified-mount #mvu-battle-inline-host .battle-shell:not([data-cabin-plane]):not([data-cabin-flow])::after,
  #detailModal #mvu-battle-inline-host .battle-shell:not([data-cabin-plane]):not([data-cabin-flow])::after,
  body.mvu-layout-holo #mvu-unified-mount #mvu-battle-inline-host .resource-fill::after,
  #detailModal #mvu-battle-inline-host .resource-fill::after,
  body.mvu-layout-holo #mvu-unified-mount #mvu-battle-inline-host .battle-alert-card,
  #detailModal #mvu-battle-inline-host .battle-alert-card {
    animation: none;
  }
}
